import pandas as pd

# Check if mention_ids or mention_names exists and is not empty
if 'mention_ids' in df.columns:
    mention_col = 'mention_ids'
elif 'mention_names' in df.columns:
    mention_col = 'mention_names'
else:
    mention_col = None

if mention_col is None or df[mention_col].dropna().empty:
    result = False
else:
    all_mentions = df[mention_col].explode().dropna()

    if all_mentions.empty:
        result = False
    else:
        most_mentioned = all_mentions.value_counts().idxmax()

        exploded_df = df[[mention_col, 'retweets']].explode(mention_col).dropna(subset=[mention_col])
        retweets_per_mention = exploded_df.groupby(mention_col)['retweets'].sum()

        if retweets_per_mention.empty:
            most_retweeted_mentioned = None
        else:
            most_retweeted_mentioned = retweets_per_mention.idxmax()

        result = bool(most_mentioned == most_retweeted_mentioned)
